records.question:
What is the solution to the following equation?
\begin{equation}
P''(u)+2\lambda\left(\coth u+\tanh u\right)P'(u)+4(\lambda^2+\sigma^2) P(u)=0.
\end{equation}

In the $N=3$ case, there is a function $f$ of $\chi$ such that
\begin{equation}
Y_\sigma(\chi) = C^\lambda_{i\sigma-\lambda}(f(\chi))
\end{equation}
up to some constant factor in $\sigma$ and $\lambda$.
What is $f$?

Assume $\gamma(x)\neq 0$ and $S\equiv 0$ for $x\ge x_s$ (production stops at $x_s$).
\begin{enumerate}
\item Use \eqref{eq:number_conservation_condition} to show that
\begin{equation}\label{eq:N_of_x}
\mathcal{N}(x)=\frac{Y_2(x)}{2}.
\end{equation}
\item Show that for $x\ge x_s$, the moment equations close as
\begin{equation}\label{eq:moment_odes}
\partial_x Y_2(x)=0,\qquad
\partial_x Y_3(x)=\gamma(x)\big(3Y_2(x)-Y_3(x)\big),\qquad
\partial_x Y_4(x)=\gamma(x)\big(12Y_2(x)-Y_4(x)\big).
\end{equation}
\end{enumerate}

Show that there exist scalar functions $p(s),q(s)$ such that
\begin{align}
e^{sU}=p(s)\,I+q(s)\,U,
\label{eq:exp-reduce}
\end{align}
and derive the coupled linear ODE system
\begin{align}
p'(s)=...,\qquad q'(s)=...,
\qquad
p(0)=1,\ q(0)=0.
\label{eq:pq-ode}
\end{align}

Using \eqref{eq:frechet-exp} and the reduction \eqref{eq:exp-reduce},
show that the Fr\'echet derivative can be written in the \emph{four-term noncommutative basis}
\begin{align}
D(e^U)[E] \;=\; A\,E \;+\; B\,E\,U \;+\; C\,U\,E \;+\; D\,U\,E\,U,
\label{eq:frechet-basis}
\end{align}
for scalar coefficients $A,B,C,D$ depending only on $(t,d)$.
Then compute $A,B,C,D$ explicitly in terms of $\lambda_\pm$.

records.gold_answer:
\begin{align}
B&=C
=\frac{1}{(\Delta\lambda)^2}\left[
\frac{(\lambda_++\lambda_-)\,e^{\lambda_-}\big(e^{\Delta\lambda}-1\big)}{\Delta\lambda}
-\lambda_+e^{\lambda_-}-\lambda_-e^{\lambda_+}
\right],
\\[6pt]
D&=\frac{1}{(\Delta\lambda)^2}\left[
e^{\lambda_+}+e^{\lambda_-}
-\frac{2e^{\lambda_-}\big(e^{\Delta\lambda}-1\big)}{\Delta\lambda}
\right],
\\[6pt]
A&=\frac{1}{(\Delta\lambda)^2}\left[
\lambda_+^2 e^{\lambda_-}+\lambda_-^2 e^{\lambda_+}
-\frac{2\lambda_+\lambda_-\,e^{\lambda_-}\big(e^{\Delta\lambda}-1\big)}{\Delta\lambda}
\right],
\end{align}
where $\Delta\lambda\equiv\lambda_+-\lambda_-$.

records.question:
Compute the convergent constant
\begin{align}
\mathcal{K}:=\lim_{N\to\infty}\Big(S_{1,2}(N)+S_{2,1}(N)\Big),
\end{align}
and express it in terms of $\pi$, Catalan's constant $G$, and $\zeta(3)$.

For Higgs scattering, the amplitude after contracting with $u,v$ is given by
\begin{equation}
\mathcal{M}^{ijkl} u^iv^ju^kv^l = \vec{p}(u,v)\cdot(C_{S,0},C_{S,1},C_{S,2})
\end{equation}
where $C_{S,0},C_{S,1},C_{S,2}$ are the Wilson coefficients of Higgs operators, and the 3-dimensional vector $\vec{p}(u,v)=\{p_1,p_2,p_3\}$ satisfies $p_3-p_2\geq0,\;p_2\geq0,\;p_1-p_3\geq0$. What are the constraints on $C_{S,0},C_{S,1},C_{S,2}$ from the positivity bound?

Using \eqref{eq:kernelK0} and \eqref{eq:chi_transform}, show that
\begin{equation}\label{eq:chi0_digamma}
\chi_0(\nu)=2\psi(1)-\psi\!\left(\frac12+i\nu\right)-\psi\!\left(\frac12-i\nu\right).
\end{equation}

Define a modified kernel
\begin{equation}\label{eq:K1def}
K_1(t)\equiv |t|\,K_0(t)=\frac{|t|}{2\sinh(|t|/2)},
\end{equation}
and the corresponding operator
\[
(\mathcal{K}_1 f)(\rho)\equiv \int d\rho'\;K_1(\rho-\rho')\big(f(\rho')-f(\rho)\big).
\]
Show that $\phi_\nu$ is still an eigenfunction and that its eigenvalue is
\begin{equation}\label{eq:chi1_second_derivative}
\chi_1(\nu)\equiv \chi_{K_1}(\nu)= -\frac{d^2}{d\nu^2}\chi_0(\nu).
\end{equation}

Assume \eqref{eq:response_def}. Show that to leading order in the response,
\begin{equation}
\mathrm{Cov}_{\rm SSC}(O_i,O_j)= O_i'\,O_j'\,\sigma_b^2,
\qquad
\sigma_b^2\equiv \mathrm{Var}(\delta_b).
\label{eq:SSC_rank1}
\end{equation}
Then specialize to the bandpowers \eqref{eq:P_response} and show
\begin{equation}
\mathrm{Cov}_{\rm SSC}\big(\widehat P(k_i),\widehat P(k_j)\big)
= R(k_i)P(k_i)\,R(k_j)P(k_j)\,\sigma_b^2.
\label{eq:SSC_Pk}
\end{equation}

Take a Gaussian window
\begin{equation}
W(\mathbf{x})=\exp\!\left(-\frac{|\mathbf{x}|^2}{2R^2}\right),
\qquad R>0.
\label{eq:W_gauss}
\end{equation}
Show that
\begin{equation}
\frac{|\widetilde W(\mathbf{k})|^2}{|\widetilde W(\mathbf{0})|^2}=\exp(-R^2 k^2),
\label{eq:Wratio}
\end{equation}
and hence
\begin{equation}
\sigma_b^2=\int\frac{d^3q}{(2\pi)^3}\,P(q)\,e^{-R^2 q^2}.
\label{eq:sigma_general}
\end{equation}
Now assume a toy power spectrum
\begin{equation}
P(q)=A\,e^{-q^2/q_0^2},\qquad A>0,\ q_0>0,
\label{eq:Ptoy_n0}
\end{equation}
and compute $\sigma_b^2$ in closed form.

Now take the running coupling \eqref{eq:running_alpha}. Laplace-transform \eqref{eq:evolution_general} in $Y$ and show that
$\widetilde\Phi(t,\omega)$ satisfies the inhomogeneous ODE
\begin{equation}\label{eq:laplace_ode_inhom}
\omega\,\widetilde\Phi(t,\omega)-\Phi_0(t)=\frac{1}{b\,t}\left(\chi_0\,\widetilde\Phi(t,\omega)+\frac{\chi_2}{2}\,\partial_t^2\widetilde\Phi(t,\omega)\right).
\end{equation}
Then write down the corresponding homogeneous equation (drop $\Phi_0$).

Consider the homogeneous ODE \eqref{eq:airy_form_pre} on $t\in[0,\infty)$.
Impose the boundary conditions
\begin{equation}\label{eq:dirichlet_bc}
\widetilde\Phi(t,\omega)\text{ decays as }t\to\infty,\qquad \widetilde\Phi(0,\omega)=0.
\end{equation}
(i) Show that the change of variables
\begin{equation}\label{eq:s_change}
s=\left(\frac{\omega}{A}\right)^{1/3}\left(t-\frac{B}{\omega}\right)
\end{equation}
reduces \eqref{eq:airy_form_pre} to the Airy equation $\phi''(s)-s\phi(s)=0$.
(ii) Conclude that the decaying solution is proportional to $\mathrm{Ai}(s)$.
(iii) Derive the discrete eigenvalue condition and solve for $\omega_n$ in terms of Airy zeros $a_n$.

Take the running coupling \eqref{eq:running_alpha}. Laplace-transform \eqref{eq:evolution_general} in $Y$, then write down the corresponding homogeneous equation (drop $\Phi_0$).
Assume a Robin/matching condition at $t=0$:
\begin{equation}\label{eq:robin_bc}
\widetilde\Phi(t,\omega)\text{ decays as }t\to\infty,\qquad
\widetilde\Phi'(0,\omega)+r\,\widetilde\Phi(0,\omega)=0,
\end{equation}
where $r$ is a fixed real constant.
Do a change of variable
\begin{equation}\label{eq:s_change}
s=\left(\frac{\omega}{A}\right)^{1/3}\left(t-\frac{B}{\omega}\right)
\end{equation}
with $A=\frac{\chi_2}{2b}, B=\frac{\chi_0}{b}$, and derive the Robin quantization condition as an implicit equation for $\omega$ in terms of Airy function.

